CREATE OR REPLACE FUNCTION yt_growth.reserve_v2_call(p jsonb) RETURNS jsonb LANGUAGE plpgsql AS $f$
DECLARE u yt_growth.resource_usage%ROWTYPE; ec yt_growth.external_calls%ROWTYPE; cached jsonb; g yt_growth.free_grants%ROWTYPE; cat text:=p->>'call_category'; reason text; dl int:=0; tok bigint:=coalesce((p->>'reserve_tokens')::bigint,0);
BEGIN
 IF NOT EXISTS(SELECT 1 FROM yt_growth.production_jobs j WHERE j.job_id=p->>'job_id' AND j.lease_owner=p->>'execution_id' AND j.lease_until>now()) THEN RETURN p || '{"governor":"BLOCK","governor_reason":"Lease missing"}'::jsonb; END IF;
 INSERT INTO yt_growth.resource_usage(job_id) VALUES(p->>'job_id') ON CONFLICT DO NOTHING;
 SELECT * INTO u FROM yt_growth.resource_usage WHERE job_id=p->>'job_id' FOR UPDATE;
 SELECT * INTO ec FROM yt_growth.external_calls WHERE job_id=p->>'job_id' AND call_key=p->>'call_key';
 IF ec.status='SUCCESS' AND ec.cache_until>now() THEN RETURN p || jsonb_build_object('governor','CACHE','response',ec.response); END IF;
 IF cat='stock' THEN SELECT response INTO cached FROM yt_growth.stock_query_cache WHERE provider=p#>>'{request,auth}' AND query_hash=p->>'request_hash' AND expires_at>now(); IF cached IS NOT NULL THEN RETURN p || jsonb_build_object('governor','CACHE','response',cached); END IF; END IF;
 IF coalesce(ec.attempts,0)>=(p#>>'{config,max_retries}')::int THEN reason:='MAX_RETRIES';
 ELSIF u.external_calls>=(p#>>'{config,max_external_calls}')::int THEN reason:='MAX_EXTERNAL_CALLS';
 ELSIF greatest(u.active_ms,coalesce((p->>'active_ms')::bigint,0))>(p#>>'{config,max_job_duration}')::bigint*1000 THEN reason:='MAX_JOB_DURATION';
 ELSIF cat='ai' AND u.ai_calls>=(p#>>'{config,max_ai_calls}')::int THEN reason:='MAX_AI_CALLS';
 ELSIF cat='vision' AND u.vision_calls>=(p#>>'{config,max_vision_calls}')::int THEN reason:='MAX_VISION_CALLS';
 ELSIF cat='render' AND u.render_attempts>=9 THEN reason:='MAX_RENDER_ATTEMPTS'; END IF;
 IF cat='render' AND coalesce(ec.attempts,0)=0 THEN dl:=coalesce((p->>'reserve_downloads')::int,0); END IF;
 IF u.downloads_reserved+dl>(p#>>'{config,max_asset_downloads}')::int THEN reason:='MAX_ASSET_DOWNLOADS'; END IF;
 IF reason IS NOT NULL THEN RETURN p || jsonb_build_object('governor','BLOCK','governor_reason',reason); END IF;
 IF p#>>'{request,auth}'='ai' THEN
  IF p#>'{config,free_grant}' IS NULL OR p#>'{config,free_grant}'='null'::jsonb THEN RETURN p || '{"governor":"FREE_FALLBACK","governor_reason":"Kios free entitlement unknown"}'::jsonb; END IF;
  INSERT INTO yt_growth.free_grants(grant_id,expires_at) VALUES(p#>>'{config,free_grant,grant_id}',(p#>>'{config,free_grant,expires_at}')::timestamptz) ON CONFLICT DO NOTHING;
  SELECT * INTO g FROM yt_growth.free_grants WHERE grant_id=p#>>'{config,free_grant,grant_id}' FOR UPDATE;
  IF g.expires_at<=now() OR g.calls_used>=(p#>>'{config,free_grant,max_requests}')::int OR g.tokens_reserved+tok>(p#>>'{config,free_grant,max_tokens}')::bigint THEN RETURN p || '{"governor":"FREE_FALLBACK","governor_reason":"Kios free grant exhausted"}'::jsonb; END IF;
  UPDATE yt_growth.free_grants SET calls_used=calls_used+1,tokens_reserved=tokens_reserved+tok WHERE grant_id=g.grant_id;
 END IF;
 UPDATE yt_growth.resource_usage SET external_calls=external_calls+1,ai_calls=ai_calls+(cat='ai')::int,vision_calls=vision_calls+(cat='vision')::int,research_calls=research_calls+(cat='research')::int,tts_calls=tts_calls+(cat='tts')::int,render_attempts=render_attempts+(cat='render')::int,downloads_reserved=downloads_reserved+dl,active_ms=greatest(active_ms,coalesce((p->>'active_ms')::bigint,0)),updated_at=now() WHERE job_id=p->>'job_id';
 INSERT INTO yt_growth.external_calls(job_id,call_key,operation,status,attempts,request_hash,started_at) VALUES(p->>'job_id',p->>'call_key',p->>'operation','IN_FLIGHT',1,p->>'request_hash',now()) ON CONFLICT(job_id,call_key) DO UPDATE SET status='IN_FLIGHT',attempts=yt_growth.external_calls.attempts+1,started_at=now(),updated_at=now();
 RETURN p || jsonb_build_object('governor','ALLOW','external_attempt',coalesce(ec.attempts,0)+1);
END $f$;
